items = ['tape dispenser','extension cord','swimming goggles','snow goggles','throw pillows','juicer','paint cans']

# Use existing amazon_token from earlier blocks
print('amazon_token_exists', 'amazon_token' in globals(), 'amazon_token_set', bool(globals().get('amazon_token')))

best_by_item = {}
scan_stats = {}

for item in items:
    page_index = 0
    page_limit = 20
    candidates = []
    total_scanned = 0
    while True:
        res = apis.amazon.search_products(query=item, page_index=page_index, page_limit=page_limit)
        # res should be a list
        if not res:
            break
        total_scanned += len(res)
        # filter inventory available
        for p in res:
            inv = p.get('inventory_quantity', 0)
            if inv is None:
                inv = 0
            if inv >= 1:
                candidates.append(p)
        print('item', item, 'page', page_index, 'returned', len(res), 'candidates', len(candidates))
        if len(res) < page_limit:
            break
        page_index += 1
    scan_stats[item] = {'total_scanned': total_scanned, 'available_candidates': len(candidates)}
    if not candidates:
        best_by_item[item] = None
        print('item', item, 'NO_AVAILABLE_CANDIDATES')
        continue
    # Choose highest rating, then cheaper price
    # Deterministic tiebreaker: lower product_id
    def sort_key(p):
        return (-p.get('rating', 0), p.get('price', float('inf')), p.get('product_id', 10**18))
    best = sorted(candidates, key=sort_key)[0]
    best_by_item[item] = best
    print('item', item, 'best_product_id', best['product_id'], 'best_name', best['name'],
          'rating', best.get('rating'), 'price', best.get('price'), 'inv', best.get('inventory_quantity'),
          'reviews', best.get('num_product_reviews'))

print('scan_stats', scan_stats)

